do $$ declare def text; begin select pg_get_functiondef('public.guard_financial_correction()'::regprocedure) into def; def:=replace(def,'if new.total_payable<paid or new.total_payable<>new.principal+round(new.principal*new.interest_rate/100)-waived then','if new.total_payable<paid or ((new.principal<>old.principal or new.interest_rate<>old.interest_rate) and new.total_payable<>new.principal+round(new.principal*new.interest_rate/100)-waived) then');execute def;end $$;